command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: VERBORGENER WURF (Ausführung - Stumpfe Version, Neues Layout)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Verborgener Wurf";
    const ahne = "Rondra";
    const finalEffektName = `${gabenName} (${ahne})`;
    const iconBild = DSK_FW.Symbol(ahne);

    if (DSK_FW.EffektEnde && !globalThis._dskVerborgenerWurfRegistered) {
        globalThis._dskVerborgenerWurfRegistered = true;
        DSK_FW.EffektEnde.Register("verborgenerWurf", finalEffektName, "Die verschleiernden Schatten verziehen sich. Der Verborgene Wurf ist nicht mehr aktiv und das Ziel wird wieder sichtbar.");
    }

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. CASTER ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    let casterToken = casterActor.getActiveTokens()[0] || canvas.tokens.controlled[0];
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der Szene für die Entfernungsberechnung!");

    const qsWert = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");
    let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(casterActor)])].filter(id => game.users.get(id));

    // --- 3. LIVE-WÄCHTER FÜR SINNESSCHÄRFE (STUMPF & DIREKT) ---
    if (globalThis._dskVerborgenerWurfHookId) {
        Hooks.off("createChatMessage", globalThis._dskVerborgenerWurfHookId);
    }

    globalThis._dskVerborgenerWurfHookId = Hooks.on("createChatMessage", async (msgObj) => {
        // Ignoriere Systemnachrichten und unsere eigenen Flüsternachrichten
        if (msgObj.speaker?.alias === "System") return;
        if (msgObj.flags?.dsk?.isWatcherMsg) return;

        // Damit nicht alle Spieler gleichzeitig das Makro feuern, rechnet nur derjenige, der gewürfelt hat
        const authorId = msgObj.author?.id || msgObj.user?.id;
        if (authorId !== game.user.id) return;

        // Simpelster Textabgleich
        const rawContent = String(msgObj.flavor || "") + " " + String(msgObj.content || "");
        if (!rawContent.toLowerCase().includes("sinnessch")) return;

        // Finde alle geschützten Ziele
        let hoechsteQS = 0;
        let alleVerborgenenNamen = [];

        for (let t of canvas.tokens.placeables) {
            if (t.actor) {
                const buff = t.actor.effects.find(e => e.getFlag("dsk", "isVerborgenerWurf"));
                if (buff) {
                    const qs = buff.getFlag("dsk", "qs") || 1;
                    if (qs > hoechsteQS) hoechsteQS = qs;
                    alleVerborgenenNamen.push(t.name);
                }
            }
        }

        // Wenn niemand verborgen ist, brich ab
        if (alleVerborgenenNamen.length === 0) return;

        const erschwernis = hoechsteQS * 2;
        const angreiferName = msgObj.speaker?.alias || "Ein Suchender";

        // --- NEUES LAYOUT: Kein roter Kasten, Information-Kopf & angepasste Pfotenliste ---
        const mathHtml = `
            <p style="margin-bottom: 8px;">Wenn du versuchst jemanden wahrzunehmen, greift der Effekt <b>Verborgener Wurf</b>.</p>
            <p style="margin-bottom: 4px; font-weight: bold; color: #76301b;">Vorgehen:</p>
            <ul class="dsklist" style="margin-top: 0; margin-bottom: 0;">
                <li>Ziehe <b>${erschwernis}</b> von deinem Probenwert ab.</li>
                <li>Vergleiche den Wurf mit dem neuen Wert.</li>
                <li><b style="color: #18940F;">Erfolg:</b> Habe bitte einen Moment Geduld, der SL beschreibt dir gleich, was du entdeckst.</li>
                <li><b style="color: #B30000;">Misserfolg:</b> Du nimmst nichts wahr.</li>
            </ul>
        `;

        const whisperHtml = `
            <div style="font-family: 'Signika', sans-serif;">
                <div class="dskbox1">
                    <p style="display:flex; gap:8px; align-items:center; margin:0;">
                        <img src="${iconBild}" style="width:28px; border:none; background:transparent;">
                        <b>Information</b>
                    </p>
                    <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">${finalEffektName}</p>
                </div>
                <div class="dskbox2" style="margin-top:10px; color:#000; font-size:0.95em;">
                    <p style="margin-bottom: 8px;">
                        <b>${angreiferName}</b> hat eine Sinnesschärfe-Probe abgelegt.
                    </p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    ${mathHtml}
                </div>
            </div>
        `;

        let whisperIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
        if (authorId) whisperIds.add(authorId);

        await ChatMessage.create({
            whisper: Array.from(whisperIds),
            content: whisperHtml,
            speaker: { alias: "System" },
            flags: { dsk: { isWatcherMsg: true } }
        });
    });

    // --- 4. FUNKTION FÜR FEHLERMELDUNGEN ---
    const sendError = async (grund) => {
        const infoHtml = `
            <div style="font-family: 'Signika', sans-serif;">
                <div class="dskbox1">
                    <p style="display:flex; gap:8px; align-items:center; margin:0;">
                        <img src="${iconBild}" style="width:28px; border:none; background:transparent;">
                        <b style="font-size: 1.05em;">Information</b>
                    </p>
                    <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">${finalEffektName}</p>
                </div>
                <div class="dskbox2" style="margin-top:10px; text-align: center;">
                    <p style="margin-bottom: 8px; color: #8b0000;"><b>Fehlschlag!</b></p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px;">${grund}</p>
                </div>
            </div>
        `;
        await ChatMessage.create({ whisper: whisperTargets, speaker: { alias: "System" }, content: infoHtml });
    };

    // --- 5. ALLE GÜLTIGEN ZIELE IN DER NÄHE SAMMELN ---
    let nahbereichsZiele = [];
    const maxDistanz = 6; // REICHWEITE AUF 6 SCHRITT
    const maxZiele = qsWert * 2;
    const seenIds = new Set();

    for (let t of canvas.tokens.placeables) {
        if (!t.actor) continue;

        let isErwachtOderTier = false;
        if (t.actor.type === "character" || t.actor.type === "npc") {
            isErwachtOderTier = true; 
        } else if (t.actor.type === "creature") {
            const species = (t.actor.system?.species?.value || t.actor.system?.details?.species || "").toLowerCase();
            isErwachtOderTier = ["erwacht", "erwachter", "erwachte", "tier", "tiere", "katze", "katzen", "hund", "hunde", "pferd", "pferde", "vogel", "vögel"].some(w => species.includes(w));
        }

        if (isErwachtOderTier) {
            const isCaster = t.actor.id === casterActor.id;
            const dist = isCaster ? 0 : Math.round(DSK_FW.Geometrie.Distanz(casterToken, t) * 10) / 10;

            if (dist <= maxDistanz) {
                if (!seenIds.has(t.id)) {
                    nahbereichsZiele.push({
                        actor: t.actor,
                        id: t.id,
                        name: isCaster ? `${t.name} (Selbst)` : t.name,
                        img: t.document.texture.src || t.actor.img || 'icons/svg/mystery-man.svg',
                        dist: dist,
                        isCaster: isCaster
                    });
                    seenIds.add(t.id);
                }
            }
        }
    }

    if (nahbereichsZiele.length === 0) {
        return sendError(`Es befinden sich keine Erwachten oder Tiere im Umkreis von ${maxDistanz} Schritt.`);
    }

    nahbereichsZiele.sort((a, b) => {
        if (a.isCaster) return -1;
        if (b.isCaster) return 1;
        return a.dist - b.dist;
    });

    // --- 6. DIALOG FÜR DIE AUSWAHL BAUEN ---
    let checkboxHtml = nahbereichsZiele.map(a => `
        <label style="display:flex; align-items:center; gap:10px; margin-bottom:6px; padding:6px; border: 1px solid #c9bca6; border-radius: 4px; background: rgba(0,0,0,0.03); cursor:pointer;">
            <input type="checkbox" name="zielId" value="${a.id}" class="ziel-checkbox" style="width: 16px; height: 16px;">
            <img src="${a.img}" width="30" height="30" style="border:none; border-radius:50%; object-fit:cover;">
            <div style="flex-grow: 1;">
                <b style="font-size: 1.1em; display: block; color: ${a.isCaster ? '#76301b' : '#000'};">${a.name}</b>
                <span style="font-size: 0.85em; color: #555;">${a.dist === 0 && !a.isCaster ? "Selber Standort" : a.isCaster ? "Wirkender" : a.dist + " Schritt entfernt"}</span>
            </div>
        </label>
    `).join("");

    const dialogContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top: 10px; margin-bottom: 10px; color: #000;">
                <p style="margin-bottom: 10px;"><b>Wen möchtest du vor fremden Blicken verbergen?</b><br>
                <i style="color:#555;">(Du darfst maximal <b>${maxZiele}</b> Ziele in deiner Nähe wählen)</i></p>
                <form id="ziel-form" style="max-height: 350px; overflow-y: auto; padding-right: 5px;">
                    ${checkboxHtml}
                </form>
            </div>
        </div>
    `;

    new Dialog({
        title: `Verborgener Wurf (Max: ${maxZiele})`,
        content: dialogContent,
        buttons: {
            confirm: {
                icon: '<i class="fas fa-eye-slash"></i>',
                label: "Verbergen!",
                callback: async (html) => {
                    const container = html instanceof jQuery ? html[0] : html;
                    const checkedBoxes = container.querySelectorAll('.ziel-checkbox:checked');
                    const selectedIds = Array.from(checkedBoxes).map(cb => cb.value);

                    if (selectedIds.length === 0) {
                        ui.notifications.warn("Luna sagt 🌙: Niemand wurde ausgewählt! Die Gabe verpufft.");
                        return;
                    }

                    // --- 7. EFFEKTE VERTEILEN ---
                    await casterActor.unsetFlag("world", "letzteGabenQS");
                    await casterActor.unsetFlag("world", "letzteGabenMessageId");

                    let affectedNames = [];
                    const dauerSekunden = qsWert * 600;
                    const erschwernis = qsWert * 2;

                    const originalUnsichtbarText = `Ein Unsichtbarer ist mit dem Sehsinn nicht mehr wahrnehmbar. Er ist natürlich trotzdem weiterhin hör-, riech- und ertastbar. Im Kampf kann ein Unsichtbarer nur angegriffen werden, wenn der Angreifer sich dessen Existenz und grober Position bewusst ist. Hierzu sind vergleichende Proben auf Sinnesschärfe und Verbergen nötig. Ist der Angreifer erfolgreich, darf er Angriffe gegen den Unsichtbaren ausführen. Sämtliche Angriffswerte im Nahkampf werden hierbei um -8 erschwert, Fernkampfangriffe sind reine Glückstreffer (gewürfelte 2 auf 2W20). Gegen Angriffe von Unsichtbaren fällt der Verteidigungswert des Angegriffenen auf 0 (siehe Seite 150). Ahnengaben, die auf Distanz gewirkt werden können, können nur auf einen Unsichtbaren gewirkt werden, wenn der Wirkende den Unsichtbaren berührt.<br><br><b>Sonderregel Verborgener Wurf:</b> Wenn sich dieses Ziel versteckt, sind Sinnesschärfe-Proben anderer, um es zu entdecken, um ${erschwernis} erschwert!`;

                    for (let id of selectedIds) {
                        let tToken = canvas.tokens.get(id);
                        if (!tToken || !tToken.actor) continue;

                        let tActor = tToken.actor;
                        affectedNames.push(tToken.name);

                        let alterEffekt = tActor.effects.find(e => e.getFlag("dsk", "isVerborgenerWurf"));
                        if (alterEffekt) await alterEffekt.delete();

                        await tActor.createEmbeddedDocuments("ActiveEffect", [{
                            name: finalEffektName,
                            icon: iconBild,
                            img: iconBild,
                            duration: { seconds: dauerSekunden },
                            description: originalUnsichtbarText,
                            statuses: ["invisible"],
                            flags: { core: { statusId: "invisible" }, dsk: { isVerborgenerWurf: true, ahne: ahne, qs: qsWert } }
                        }]);

                        await new Promise(resolve => setTimeout(resolve, 200));
                    }

                    // --- 8. FINALE CHAT NACHRICHT ---
                    const casterName = DSK_FW.ResolveTokenName(casterActor);
                    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';

                    const successContent = `
                        <div style="font-family: 'Signika', sans-serif;">
                            <div class="dskbox1">
                                <p style="display:flex; gap:8px; align-items:center; margin:0;">
                                    <img src="${iconBild}" style="width:28px; border:none; background:transparent;">
                                    <b>Wirkungsbeginn</b>
                                </p>
                                <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">${finalEffektName}</p>
                            </div>
                            <div class="dskbox2" style="margin-top:10px;">
                                <p><b>${casterName}</b> webt einen magischen Schatten über sich und seine Gefährten.</p>
                                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                                <p style="margin-bottom: 8px;">
                                    Folgende Ziele wurden durch den <b>Verborgenen Wurf</b> geschützt und erhielten den Status <b>Unsichtbar</b>:
                                </p>
                                <ul class="dsklist" style="margin-bottom: 8px;">
                                    ${affectedNames.map(n => `<li><b>${n}</b></li>`).join("")}
                                </ul>
                                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                                <p style="margin-bottom: 8px;">
                                    Wenn sich die Verborgenen mit der Fertigkeit <i>Verbergen</i> verstecken, sind Proben auf <b>Sinnesschärfe</b>, um sie zu entdecken, für alle Beobachter <b>um ${erschwernis} erschwert</b>.
                                </p>
                                <p style="text-align:center; font-weight:bold;">Wirkungsdauer:<br>${qsWert * 10} Minuten <span ${thinStyle}>(${qsWert} QS)</span></p>
                            </div>
                        </div>
                    `;

                    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
                    if (msg) {
                        await msg.update({ content: successContent });
                    } else {
                        await ChatMessage.create({ content: successContent, speaker: { alias: "System" } });
                    }
                }
            },
            cancel: {
                icon: '<i class="fas fa-times"></i>',
                label: "Abbrechen"
            }
        },
        default: "confirm",
        render: (html) => {
            const container = html instanceof jQuery ? html[0] : html;
            const checkboxes = container.querySelectorAll('.ziel-checkbox');

            checkboxes.forEach(cb => {
                cb.addEventListener('change', () => {
                    const checkedCount = container.querySelectorAll('.ziel-checkbox:checked').length;
                    if (checkedCount > maxZiele) {
                        cb.checked = false;
                        ui.notifications.warn(`Luna sagt 🌙: Halt! Deine QS reicht nur für maximal ${maxZiele} Ziele!`);
                    }
                });
            });

            const btns = container.querySelectorAll('.dialog-button');
            btns.forEach(btn => {
                btn.style.background = 'linear-gradient(#76301b,#582617)';
                btn.style.color = '#f8f6f5';
                btn.style.border = '1px solid #000';
                btn.style.fontWeight = 'bold';
            });
        }
    }).render(true);
})();
